BASE='''
*{box-sizing:border-box}#root{position:absolute;inset:0;overflow:hidden;background:#101b38;color:#fff1c5;font-family:Inter;font-weight:700}.clip{position:absolute;inset:0}.art{position:absolute;background-image:url('assets/storyboard.png');background-size:300% 200%;width:1080px;height:1080px;left:0;top:0}.right{position:absolute;left:1170px;top:145px;width:625px}.eyebrow{font-family:Oswald;font-size:34px;letter-spacing:5px;color:#38d8ed;margin-bottom:32px}.big{font-family:'Archivo Black';font-weight:900;font-size:94px;line-height:1.02;letter-spacing:-3px;margin:0}.body{font-size:38px;line-height:1.35}.label{display:inline-block;background:#ffe8ab;color:#101b38;padding:18px 24px;font-family:Oswald;font-size:38px;box-shadow:8px 8px 0 #ef3857}.speech{position:absolute;left:1120px;top:665px;width:665px;padding:27px 32px;background:#fff5d9;color:#101b38;font-size:39px;line-height:1.17;border:5px solid #101b38;box-shadow:11px 11px 0 #38d8ed}.small{font-size:28px;line-height:1.35}.fullart{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.stripe{position:absolute;left:1070px;top:0;width:14px;height:1080px;background:#ef3857}.stamp{position:absolute;font-family:'Archivo Black';font-size:80px;background:#ffe8ab;color:#101b38;padding:20px 38px;border:6px solid #101b38;box-shadow:10px 10px 0 #ef3857}.receipt{position:absolute;left:1250px;top:650px;width:320px;height:350px;background:#fff5d9;color:#101b38;padding:35px 28px;clip-path:polygon(0 0,100% 0,100% 95%,90% 100%,80% 95%,70% 100%,60% 95%,50% 100%,40% 95%,30% 100%,20% 95%,10% 100%,0 95%);font-family:'Space Mono';font-size:25px;text-align:center}.receipt hr{border:0;border-top:4px dashed #101b38;margin:24px 0}.dots{position:absolute;inset:0;background-image:radial-gradient(#ffe8ab 1px,transparent 1px);background-size:12px 12px;opacity:.08;pointer-events:none}.footer{position:absolute;left:108px;bottom:48px;font-size:28px;color:#c2d6df}.scene-kicker{position:absolute;left:108px;top:92px;font-family:Oswald;font-size:34px;letter-spacing:5px}.screen{position:absolute;left:480px;top:162px;width:1330px;height:810px;background:#f5f8f6;overflow:hidden;border:8px solid #fff5d9;box-shadow:15px 15px 0 #ef3857}.screen img{position:absolute;left:0;width:100%;height:auto}.side{position:absolute;left:108px;top:260px;width:320px}.side .big{font-size:49px;letter-spacing:-1px}.side .body{font-size:32px}.badge{display:inline-block;margin-top:30px;padding:16px;background:#38d8ed;color:#101b38;font-size:28px;line-height:1.25}.bubble{position:absolute;padding:22px 32px;background:#fff5d9;color:#101b38;border:5px solid #101b38;font-size:39px;line-height:1.2;box-shadow:9px 9px 0 #ef3857}.bubble:after{content:'';position:absolute;bottom:-25px;left:40px;border-top:24px solid #fff5d9;border-right:28px solid transparent}
'''
def clip(id,s,d,body):return f'<div id="{id}" class="clip" data-start="{s}" data-duration="{d}" data-track-index="2">{body}</div>'
def art(panel,id='art',style=''):
    x=[0,50,100][panel%3]; y=0 if panel<3 else 100
    return f'<div id="{id}" class="art" style="background-position:{x}% {y}%;{style}" data-layout-ignore></div>'
def write(name,dur,body,js,css=''):
    (R/'compositions'/f'{name}.html').write_text(f'''<template><style>{BASE}{css}</style><div id="root" data-composition-id="{name}" data-width="1920" data-height="1080" data-duration="{dur}">{body}</div><script>const tl=gsap.timeline({{paused:true}});{js}window.__timelines=window.__timelines||{{}};window.__timelines['{name}']=tl;</script></template>''')
# METROPOLIS / domestic / receipt
b=clip('city-view',0,4.5,art(0,'city-art','width:1920px;background-size:300% 200%;')+'<div style="position:absolute;left:108px;top:112px"><div class="label">AN ORDINARY DAY IN METROPOLIS.</div></div>')
b+=clip('domestic',4.5,3.5,art(1,'domestic-art')+'<div class="stripe"></div><div class="right"><div class="eyebrow">WITH GREAT PURCHASES...</div><h1 class="big">MOSTLY<br>KEEPING<br>RECEIPTS.</h1></div>')
b+=clip('receipt-intro',5.0,3,'<div id="receipt-in" class="receipt" data-layout-ignore style="left:1290px;top:610px"><b>LEXCORP</b><hr>WASHING MACHINE<br><br>PAID IN FULL<hr>KEEP THIS.</div><div id="receipt-note" class="label" style="position:absolute;left:1130px;top:520px">THIS WILL BE IMPORTANT.</div>')
