for id,s,d,copy in [('complete-one',2.45,1.3,'CYCLE COMPLETE!'),('what',3.85,.9,'...WHAT?'),('complete-two',4.85,1.3,'CYCLE COMPLETE!'),('app-demand',6.2,2.0,'FOR BEST RESULTS,<br>DOWNLOAD THE<br>LEXCORP APP.'),('furious-line',7.95,1.35,'ARE YOU<br>KIDDING ME?!'),('thanks',9.3,1.7,'THANK YOU FOR<br>CHOOSING LEXCORP!')]:
    b+=clip('wash-'+id,s,d,f'<div id="wash-{id}-ink" class="speech">{copy}</div>')
write('washer',11,b,"tl.fromTo('#washer-normal',{scale:1},{scale:1.035,duration:3.55,ease:'none'});tl.fromTo('#washer-fury',{scale:1.05},{scale:1.14,duration:7.3,ease:'none'},3.6);"+''.join(f"tl.fromTo('#wash-{id}-ink',{{scale:.88,y:20}},{{scale:1,y:0,duration:.18,ease:'back.out(1.5)'}},{s});" for id,s in [('complete-one',2.45),('what',3.85),('complete-two',4.85),('app-demand',6.2),('furious-line',7.95),('thanks',9.3)]))
